<body>
<main class="app">
  <h1>航站终端</h1>
  <div class="grid">
    <div class="cell"><div class="label">区域</div><b id="area">读取中</b></div>
    <div class="cell"><div class="label">天气</div><b id="weather">读取中</b></div>
    <div class="cell"><div class="label">任务</div><b id="task">读取中</b></div>
  </div>
  <button id="act">把“前往核对灯标”写入输入框</button>
  <div id="status" class="status">正在连接宿主……</div>
</main>
<script>
(() => {
  'use strict';
  const q = id => document.getElementById(id);
  const subscriptions = [];
  let messageId = null;

  function parseSnapshot(text) {
    const match = String(text ?? '').match(/<航站状态>([\s\S]*?)<\/航站状态>/);
    if (!match) return null;
    return Object.fromEntries(match[1].split(/\r?\n/).map(line => line.trim()).filter(Boolean).map(line => {
      const at = line.indexOf('=');
      return at < 0 ? [line, ''] : [line.slice(0, at).trim(), line.slice(at + 1).trim()];
    }));
  }

  async function refresh() {
    try {
      if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') {
        throw new Error('当前不是 Tavern Helper 消息 iframe');
      }
      messageId = getCurrentMessageId();
      const message = getChatMessages(messageId)[0];
      const data = parseSnapshot(message?.message);
      if (!data) throw new Error('当前楼层缺少 <航站状态>');
      q('area').textContent = data.区域 || '未记录';
      q('weather').textContent = data.天气 || '未记录';
      q('task').textContent = data.任务 || '未记录';
      q('status').textContent = `已读取第 ${messageId} 楼`;
    } catch (error) {
      q('area').textContent = q('weather').textContent = q('task').textContent = '不可用';
      q('status').textContent = `读取失败：${error.message}`;
    }
  }

  q('act').addEventListener('click', async () => {
    const text = '前往北栈桥核对灯标。';
    try {
      const bridge = window.航站输入桥 || window.parent?.航站输入桥;
      if (bridge?.setInput) {
        await bridge.setInput(text);
        q('status').textContent = '已写入输入框，可继续编辑后发送。';
        return;
      }
      throw new Error('输入桥未启用');
    } catch (error) {
      q('status').textContent = `${error.message}；请手动复制：${text}`;
    }
  });

  if (typeof eventOn === 'function' && typeof tavern_events === 'object') {
    for (const eventName of [tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_SWIPED]) {
      if (!eventName) continue;
      subscriptions.push(eventOn(eventName, id => {
        if (Number(id) === messageId) refresh();
      }));
    }
  }
  addEventListener('pagehide', () => subscriptions.forEach(item => item?.stop?.()), { once: true });
  refresh();
})();
</script>
</body>
</html>
